<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rencana Perjalanan</title><style>body{font-family:Arial;margin:0;color:#171717}.wrap{max-width:1000px;margin:auto;padding:28px 18px}.card{padding:20px;border:1px solid #e5e7eb;border-radius:14px;margin:16px 0}input,textarea{box-sizing:border-box;width:100%;padding:11px;border:1px solid #d4d4d4;border-radius:8px;margin:7px 0 14px}label{font-weight:bold}.btn{padding:10px 14px;border:1px solid #ddd;background:white;border-radius:8px;text-decoration:none;color:#222;cursor:pointer}.red{background:#dc2626;color:white;border-color:#dc2626}.progress{height:12px;background:#e5e7eb;border-radius:20px;overflow:hidden}.bar{height:100%;background:#16a34a}form{margin:8px 0}.place{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:12px 0;border-top:1px solid #eee}.muted{color:#737373}</style></head><body><main class="wrap"><a href="{{ route('profile.show') }}">← Profil</a><h1>▦ Rencana Perjalanan</h1>@if(session('success'))<p style="color:green">{{ session('success') }}</p>@endif @if($errors->any())<div style="color:#b91c1c">@foreach($errors->all() as $error)<p>{{ $error }}</p>@endforeach</div>@endif
<section class="card"><h2>Buat rencana baru</h2><form method="POST" action="{{ route('trips.store') }}">@csrf<label>Nama perjalanan</label><input name="title" required maxlength="255" placeholder="Contoh: Liburan ke Bali"><label>Catatan</label><textarea name="notes" placeholder="Catatan perjalanan"></textarea><label>Tanggal mulai</label><input type="date" name="start_date"><label>Tanggal selesai</label><input type="date" name="end_date"><button class="btn red">Buat Rencana</button></form></section>
@forelse($plans as $trip)<section class="card"><h2>{{ $trip->title }} @if($trip->completed_at) 🏆 Selesai @endif</h2><p class="muted">{{ $trip->start_date?->format('d M Y') ?? 'Tanggal belum ditentukan' }} @if($trip->end_date) – {{ $trip->end_date->format('d M Y') }} @endif</p>@if($trip->notes)<p>{{ $trip->notes }}</p>@endif<div class="progress"><div class="bar" style="width:{{ $trip->progress }}%"></div></div><p><strong>{{ $trip->progress }}%</strong> · {{ $trip->visited_places_count }} dari {{ $trip->places_count }} tujuan dikunjungi</p>
@if(!$trip->completed_at)<form method="POST" action="{{ route('trips.places.store',$trip) }}">@csrf<h3>Tambah tujuan wisata</h3><label>Nama tempat</label><input name="name" required placeholder="Nama tempat dari peta"><label>Alamat</label><input name="address" placeholder="Alamat tempat"><label>Link peta (opsional)</label><input type="url" name="url" placeholder="https://maps.google.com/..."><button class="btn">+ Tambah Tujuan</button></form>@endif
@forelse($trip->places as $place)<div class="place"><div style="flex:1"><strong>{{ $place->name }}</strong>@if($place->address)<div class="muted">{{ $place->address }}</div>@endif @if($place->url)<a href="{{ $place->url }}" target="_blank" rel="noopener">Buka peta</a>@endif</div>@if(!$trip->completed_at)<form method="POST" action="{{ route('trips.places.toggle',[$trip,$place]) }}">@csrf @method('PATCH')<button class="btn">{{ $place->visited ? '✓ Sudah dikunjungi (batalkan)' : 'Tandai dikunjungi' }}</button></form>@else<span>✓ Selesai</span>@endif</div>@empty<p class="muted">Belum ada tujuan. Tambahkan tempat wisata di atas.</p>@endforelse
@if(!$trip->completed_at)<form method="POST" action="{{ route('trips.complete',$trip) }}">@csrf<button class="btn red" {{ $trip->places_count === 0 || $trip->visited_places_count !== $trip->places_count ? 'disabled' : '' }}>Tandai Perjalanan Selesai</button></form><form method="POST" action="{{ route('trips.destroy',$trip) }}" onsubmit="return confirm('Hapus rencana ini?')">@csrf @method('DELETE')<button class="btn">Hapus Rencana</button></form>@endif</section>@empty<p>Belum ada rencana perjalanan.</p>@endforelse</main></body></html>
